import pytest
from collections import OrderedDict
from collections.abc import Mapping
from toolz.dicttoolz import (
    merge, merge_with, valmap, keymap, itemmap,
    valfilter, keyfilter, itemfilter,
    assoc, dissoc, assoc_in, update_in, get_in
)


# ── get_in ────────────────────────────────────────────────────────────────────

def test_get_in_simple():
    assert get_in(['a'], {'a': 1}) == 1

def test_get_in_nested():
    assert get_in(['a', 'b'], {'a': {'b': 42}}) == 42

def test_get_in_list_index():
    assert get_in([0], [10, 20, 30]) == 10

def test_get_in_mixed_nesting():
    d = {'purchase': {'items': ['Apple', 'Orange']}}
    assert get_in(['purchase', 'items', 0], d) == 'Apple'

def test_get_in_missing_key_returns_default():
    assert get_in(['x'], {}) is None
    assert get_in(['x'], {}, default=99) == 99

def test_get_in_missing_intermediate_key():
    assert get_in(['a', 'b'], {'a': {}}) is None

def test_get_in_no_default_raises_keyerror():
    with pytest.raises(KeyError):
        get_in(['y'], {}, no_default=True)

def test_get_in_no_default_raises_indexerror():
    with pytest.raises(IndexError):
        get_in([5], [1, 2], no_default=True)

def test_get_in_type_error_returns_default():
    # indexing into None
    assert get_in(['a', 'b'], {'a': None}) is None

def test_get_in_empty_keys():
    # empty key sequence should return the collection itself
    d = {'a': 1}
    assert get_in([], d) is d

def test_get_in_wrong_index_type():
    # string key into list → TypeError → default
    assert get_in(['bad'], [1, 2, 3], default='nope') == 'nope'


# ── merge ─────────────────────────────────────────────────────────────────────

def test_merge_empty():
    assert merge() == {}

def test_merge_single_dict():
    d = {1: 'a'}
    result = merge(d)
    assert result == {1: 'a'}

def test_merge_precedence():
    assert merge({1: 'first'}, {1: 'second'}) == {1: 'second'}

def test_merge_three_dicts():
    assert merge({'a': 1}, {'b': 2}, {'c': 3}) == {'a': 1, 'b': 2, 'c': 3}

def test_merge_does_not_mutate_inputs():
    d1 = {'a': 1}
    d2 = {'b': 2}
    merge(d1, d2)
    assert d1 == {'a': 1}
    assert d2 == {'b': 2}

def test_merge_with_factory():
    result = merge({'a': 1}, {'b': 2}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)
    assert result == {'a': 1, 'b': 2}

def test_merge_unexpected_kwarg():
    with pytest.raises(TypeError):
        merge({'a': 1}, bad_kwarg=dict)

def test_merge_empty_dicts():
    assert merge({}, {}) == {}

def test_merge_iterable_of_dicts():
    dicts = [{'a': 1}, {'b': 2}, {'c': 3}]
    assert merge(dicts) == {'a': 1, 'b': 2, 'c': 3}


# ── merge_with ────────────────────────────────────────────────────────────────

def test_merge_with_sum():
    assert merge_with(sum, {1: 1}, {1: 2}, {1: 3}) == {1: 6}

def test_merge_with_list():
    result = merge_with(list, {'a': 1, 'b': 2}, {'a': 3})
    assert result == {'a': [1, 3], 'b': [2]}

def test_merge_with_single_key():
    assert merge_with(sum, {'a': 10}) == {'a': 10}

def test_merge_with_no_dicts():
    assert merge_with(sum) == {}

def test_merge_with_iterable():
    dicts = [{'a': 1}, {'a': 2}]
    assert merge_with(sum, dicts) == {'a': 3}

def test_merge_with_factory():
    result = merge_with(sum, {'a': 1}, {'a': 2}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)
    assert result == {'a': 3}

def test_merge_with_disjoint_keys():
    assert merge_with(sum, {'a': 1}, {'b': 2}) == {'a': 1, 'b': 2}

def test_merge_with_unexpected_kwarg():
    with pytest.raises(TypeError):
        merge_with(sum, {'a': 1}, bad=dict)


# ── valmap ────────────────────────────────────────────────────────────────────

def test_valmap_empty():
    assert valmap(str, {}) == {}

def test_valmap_identity():
    d = {'a': 1, 'b': 2}
    assert valmap(lambda x: x, d) == d

def test_valmap_does_not_mutate():
    d = {'a': 1}
    valmap(lambda x: x + 1, d)
    assert d == {'a': 1}

def test_valmap_factory():
    result = valmap(str, {'a': 1}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)

def test_valmap_keys_unchanged():
    d = {1: 10, 2: 20}
    result = valmap(lambda x: x * 2, d)
    assert set(result.keys()) == {1, 2}
    assert result[1] == 20
    assert result[2] == 40


# ── keymap ────────────────────────────────────────────────────────────────────

def test_keymap_empty():
    assert keymap(str, {}) == {}

def test_keymap_values_unchanged():
    d = {1: 'a', 2: 'b'}
    result = keymap(lambda k: k * 10, d)
    assert result == {10: 'a', 20: 'b'}

def test_keymap_does_not_mutate():
    d = {1: 'a'}
    keymap(str, d)
    assert d == {1: 'a'}

def test_keymap_factory():
    result = keymap(str, {1: 'a'}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── itemmap ───────────────────────────────────────────────────────────────────

def test_itemmap_swap():
    d = {'a': 1, 'b': 2}
    result = itemmap(lambda item: (item[1], item[0]), d)
    assert result == {1: 'a', 2: 'b'}

def test_itemmap_empty():
    assert itemmap(lambda x: x, {}) == {}

def test_itemmap_factory():
    result = itemmap(lambda x: x, {'a': 1}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── valfilter ─────────────────────────────────────────────────────────────────

def test_valfilter_all_pass():
    d = {1: 2, 2: 4}
    assert valfilter(lambda x: x % 2 == 0, d) == d

def test_valfilter_none_pass():
    d = {1: 1, 2: 3}
    assert valfilter(lambda x: x % 2 == 0, d) == {}

def test_valfilter_empty():
    assert valfilter(lambda x: True, {}) == {}

def test_valfilter_does_not_mutate():
    d = {1: 2, 2: 3}
    valfilter(lambda x: x % 2 == 0, d)
    assert d == {1: 2, 2: 3}

def test_valfilter_factory():
    result = valfilter(lambda x: x > 0, {1: 1}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── keyfilter ─────────────────────────────────────────────────────────────────

def test_keyfilter_all_pass():
    d = {2: 'a', 4: 'b'}
    assert keyfilter(lambda k: k % 2 == 0, d) == d

def test_keyfilter_none_pass():
    d = {1: 'a', 3: 'b'}
    assert keyfilter(lambda k: k % 2 == 0, d) == {}

def test_keyfilter_empty():
    assert keyfilter(lambda k: True, {}) == {}

def test_keyfilter_does_not_mutate():
    d = {1: 'a', 2: 'b'}
    keyfilter(lambda k: k % 2 == 0, d)
    assert d == {1: 'a', 2: 'b'}

def test_keyfilter_factory():
    result = keyfilter(lambda k: True, {1: 'a'}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── itemfilter ────────────────────────────────────────────────────────────────

def test_itemfilter_by_both():
    d = {1: 2, 2: 3, 3: 4}
    result = itemfilter(lambda item: item[0] % 2 == 1 and item[1] % 2 == 0, d)
    assert result == {1: 2, 3: 4}

def test_itemfilter_empty():
    assert itemfilter(lambda x: True, {}) == {}

def test_itemfilter_none_pass():
    d = {1: 1, 2: 2}
    assert itemfilter(lambda x: False, d) == {}

def test_itemfilter_factory():
    result = itemfilter(lambda x: True, {1: 'a'}, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── assoc ─────────────────────────────────────────────────────────────────────

def test_assoc_new_key():
    assert assoc({}, 'a', 1) == {'a': 1}

def test_assoc_overwrite_key():
    assert assoc({'a': 1}, 'a', 99) == {'a': 99}

def test_assoc_does_not_mutate():
    d = {'a': 1}
    result = assoc(d, 'b', 2)
    assert d == {'a': 1}
    assert result == {'a': 1, 'b': 2}

def test_assoc_factory():
    result = assoc({'a': 1}, 'b', 2, factory=OrderedDict)
    assert isinstance(result, OrderedDict)
    assert result == {'a': 1, 'b': 2}


# ── dissoc ────────────────────────────────────────────────────────────────────

def test_dissoc_missing_key_ignored():
    assert dissoc({'a': 1}, 'b') == {'a': 1}

def test_dissoc_empty_dict():
    assert dissoc({}, 'a') == {}

def test_dissoc_remove_all_keys():
    assert dissoc({'a': 1, 'b': 2}, 'a', 'b') == {}

def test_dissoc_does_not_mutate():
    d = {'a': 1, 'b': 2}
    result = dissoc(d, 'a')
    assert d == {'a': 1, 'b': 2}
    assert result == {'b': 2}

def test_dissoc_no_keys_removed():
    d = {'a': 1, 'b': 2}
    result = dissoc(d)
    assert result == d

def test_dissoc_factory():
    result = dissoc({'a': 1, 'b': 2}, 'a', factory=OrderedDict)
    assert isinstance(result, OrderedDict)
    assert result == {'b': 2}

def test_dissoc_unexpected_kwarg():
    with pytest.raises(TypeError):
        dissoc({'a': 1}, 'a', bad_kwarg=dict)

def test_dissoc_many_keys_branch():
    # Force the branch where len(keys) >= len(d) * 0.6
    d = {i: i for i in range(5)}
    result = dissoc(d, 0, 1, 2, 3)
    assert result == {4: 4}


# ── assoc_in ──────────────────────────────────────────────────────────────────

def test_assoc_in_single_key():
    assert assoc_in({}, ['a'], 1) == {'a': 1}

def test_assoc_in_nested_existing():
    d = {'a': {'b': 1}}
    assert assoc_in(d, ['a', 'b'], 99) == {'a': {'b': 99}}

def test_assoc_in_creates_nested():
    assert assoc_in({}, ['a', 'b', 'c'], 42) == {'a': {'b': {'c': 42}}}

def test_assoc_in_does_not_mutate():
    d = {'a': {'b': 1}}
    result = assoc_in(d, ['a', 'b'], 2)
    assert d == {'a': {'b': 1}}
    assert result == {'a': {'b': 2}}

def test_assoc_in_factory():
    result = assoc_in({}, ['a'], 1, factory=OrderedDict)
    assert isinstance(result, OrderedDict)


# ── update_in ─────────────────────────────────────────────────────────────────

def test_update_in_simple():
    assert update_in({'a': 1}, ['a'], lambda x: x + 1) == {'a': 2}

def test_update_in_default_used_when_missing():
    assert update_in({}, ['a'], lambda x: x + 1, default=0) == {'a': 1}

def test_update_in_creates_nested():
    result = update_in({}, [1, 2, 3], str, default='x')
    assert result == {1: {2: {3: 'x'}}}

def test_update_in_does_not_mutate():
    d = {'a': 1}
    update_in(d, ['a'], lambda x: x + 1)
    assert d == {'a': 1}

def test_update_in_nested_existing():
    d = {'a': {'b': 10}}
    result = update_in(d, ['a', 'b'], lambda x: x * 2)
    assert result == {'a': {'b': 20}}

def test_update_in_factory():
    result = update_in({}, ['x'], lambda x: x, default=5, factory=OrderedDict)
    assert isinstance(result, OrderedDict)

def test_update_in_preserves_other_keys():
    d = {'a': 1, 'b': 2}
    result = update_in(d, ['a'], lambda x: x + 10)
    assert result['b'] == 2

def test_update_in_nested_preserves_sibling_keys():
    d = {'a': {'b': 1, 'c': 2}}
    result = update_in(d, ['a', 'b'], lambda x: x + 1)
    assert result == {'a': {'b': 2, 'c': 2}}


# ── factory keyword errors ────────────────────────────────────────────────────

def test_merge_with_unexpected_kwarg_raises():
    with pytest.raises(TypeError):
        merge_with(sum, {'a': 1}, unexpected=dict)


# ── return type matches factory ───────────────────────────────────────────────

def test_merge_returns_dict_by_default():
    result = merge({'a': 1}, {'b': 2})
    assert type(result) is dict

def test_valmap_returns_dict_by_default():
    result = valmap(str, {'a': 1})
    assert type(result) is dict

def test_keymap_returns_dict_by_default():
    result = keymap(str, {1: 'a'})
    assert type(result) is dict

def test_valfilter_returns_dict_by_default():
    result = valfilter(lambda x: True, {'a': 1})
    assert type(result) is dict

def test_keyfilter_returns_dict_by_default():
    result = keyfilter(lambda x: True, {'a': 1})
    assert type(result) is dict

def test_itemfilter_returns_dict_by_default():
    result = itemfilter(lambda x: True, {'a': 1})
    assert type(result) is dict


# ── edge cases ────────────────────────────────────────────────────────────────

def test_merge_with_same_dict_twice():
    d = {'a': 1}
    assert merge_with(sum, d, d) == {'a': 2}

def test_valmap_with_none_values():
    d = {'a': None, 'b': None}
    result = valmap(lambda x: 0 if x is None else x, d)
    assert result == {'a': 0, 'b': 0}

def test_keymap_collision():
    # Two keys map to the same new key; last one wins (dict behaviour)
    d = {1: 'first', 2: 'second'}
    result = keymap(lambda k: 'same', d)
    assert len(result) == 1
    assert 'same' in result

def test_dissoc_duplicate_keys_arg():
    # Passing the same key to remove multiple times should be fine
    d = {'a': 1, 'b': 2}
    result = dissoc(d, 'a', 'a')
    assert result == {'b': 2}

def test_get_in_with_zero_as_valid_value():
    d = {'a': 0}
    assert get_in(['a'], d, default=99) == 0

def test_get_in_with_false_as_valid_value():
    d = {'a': False}
    assert get_in(['a'], d, default=True) is False

def test_assoc_returns_new_object():
    d = {'a': 1}
    result = assoc(d, 'a', 1)
    assert result is not d

def test_merge_with_empty_dict_among_dicts():
    assert merge({'a': 1}, {}, {'b': 2}) == {'a': 1, 'b': 2}

def test_update_in_none_default():
    result = update_in({}, ['key'], lambda x: 'was_none' if x is None else x)
    assert result == {'key': 'was_none'}

def test_merge_with_ordered_dict():
    od1 = OrderedDict([('a', 1), ('b', 2)])
    od2 = OrderedDict([('c', 3)])
    result = merge(od1, od2)
    assert result == {'a': 1, 'b': 2, 'c': 3}

def test_itemmap_does_not_mutate():
    d = {'a': 1}
    itemmap(lambda x: x, d)
    assert d == {'a': 1}

def test_valfilter_partial_pass():
    d = {'a': 1, 'b': 2, 'c': 3, 'd': 4}
    result = valfilter(lambda v: v > 2, d)
    assert result == {'c': 3, 'd': 4}

def test_keyfilter_partial_pass():
    d = {'apple': 1, 'banana': 2, 'cherry': 3}
    result = keyfilter(lambda k: k.startswith('a'), d)
    assert result == {'apple': 1}

# -*- coding: utf-8 -*-
import pytest
from slugify.special import add_uppercase_char, CYRILLIC, GERMAN, GREEK, PRE_TRANSLATIONS


# Tests for add_uppercase_char

def test_add_uppercase_char_returns_list():
    result = add_uppercase_char([('a', 'alpha')])
    assert isinstance(result, list)


def test_add_uppercase_char_basic_lowercase():
    char_list = [('a', 'alpha')]
    result = add_uppercase_char(char_list)
    assert ('A', 'Alpha') in result


def test_add_uppercase_char_uppercase_inserted_before():
    char_list = [('a', 'alpha')]
    result = add_uppercase_char(char_list)
    upper_idx = result.index(('A', 'Alpha'))
    lower_idx = result.index(('a', 'alpha'))
    assert upper_idx < lower_idx


def test_add_uppercase_char_no_duplicate_uppercase():
    char_list = [('a', 'alpha'), ('A', 'Alpha')]
    result = add_uppercase_char(char_list)
    assert result.count(('A', 'Alpha')) == 1


def test_add_uppercase_char_already_uppercase_not_added_again():
    # If char is already uppercase (char == char.upper()), no new entry should be inserted
    char_list = [('A', 'Alpha')]
    original_len = len(char_list)
    result = add_uppercase_char(char_list)
    assert result.count(('A', 'Alpha')) == 1


def test_add_uppercase_char_empty_list():
    result = add_uppercase_char([])
    assert result == []


def test_add_uppercase_char_multiple_entries():
    char_list = [('ä', 'ae'), ('ö', 'oe'), ('ü', 'ue')]
    result = add_uppercase_char(char_list)
    assert ('Ä', 'Ae') in result
    assert ('Ö', 'Oe') in result
    assert ('Ü', 'Ue') in result


def test_add_uppercase_char_original_chars_preserved():
    char_list = [('ä', 'ae'), ('ö', 'oe')]
    result = add_uppercase_char(char_list)
    assert ('ä', 'ae') in result
    assert ('ö', 'oe') in result


def test_add_uppercase_char_modifies_in_place():
    char_list = [('a', 'alpha')]
    result = add_uppercase_char(char_list)
    assert result is char_list


def test_add_uppercase_char_cyrillic():
    char_list = [('ё', 'e')]
    result = add_uppercase_char(char_list)
    assert ('Ё', 'E') in result


def test_add_uppercase_char_capitalize_translation():
    # capitalize() means first letter uppercase, rest lowercase
    char_list = [('щ', 'sch')]
    result = add_uppercase_char(char_list)
    assert ('Щ', 'Sch') in result


def test_add_uppercase_char_single_char_translation():
    char_list = [('у', 'y')]
    result = add_uppercase_char(char_list)
    assert ('У', 'Y') in result


def test_add_uppercase_char_no_duplication_when_uppercase_already_present():
    char_list = [('ä', 'ae'), ('Ä', 'Ae')]
    result = add_uppercase_char(char_list)
    assert result.count(('Ä', 'Ae')) == 1


# Tests for CYRILLIC constant

def test_cyrillic_contains_lowercase_yo():
    assert ('ё', 'e') in CYRILLIC


def test_cyrillic_contains_uppercase_yo():
    assert ('Ё', 'E') in CYRILLIC


def test_cyrillic_contains_lowercase_ya():
    assert ('я', 'ya') in CYRILLIC


def test_cyrillic_contains_uppercase_ya():
    assert ('Я', 'Ya') in CYRILLIC


def test_cyrillic_contains_lowercase_kh():
    assert ('х', 'h') in CYRILLIC


def test_cyrillic_contains_uppercase_kh():
    assert ('Х', 'H') in CYRILLIC


def test_cyrillic_contains_lowercase_u():
    assert ('у', 'y') in CYRILLIC


def test_cyrillic_contains_uppercase_u():
    assert ('У', 'Y') in CYRILLIC


def test_cyrillic_contains_lowercase_sch():
    assert ('щ', 'sch') in CYRILLIC


def test_cyrillic_contains_uppercase_sch():
    assert ('Щ', 'Sch') in CYRILLIC


def test_cyrillic_contains_lowercase_yu():
    assert ('ю', 'u') in CYRILLIC


def test_cyrillic_contains_uppercase_yu():
    assert ('Ю', 'U') in CYRILLIC


def test_cyrillic_length():
    # 6 lowercase + 6 uppercase = 12
    assert len(CYRILLIC) == 12


def test_cyrillic_no_duplicates():
    assert len(CYRILLIC) == len(set(CYRILLIC))


def test_cyrillic_uppercase_entries_at_start():
    # Uppercase entries are inserted at the beginning
    uppercase_entries = [(c, x) for c, x in CYRILLIC if c == c.upper() and c != c.lower()]
    for entry in uppercase_entries:
        idx = CYRILLIC.index(entry)
        # All uppercase entries should appear before the first lowercase entry
        lowercase_entries = [(c, x) for c, x in CYRILLIC if c != c.upper() or c == c.lower()]
        if lowercase_entries:
            first_lower_idx = CYRILLIC.index(lowercase_entries[0])
            # This is not guaranteed in all cases since insertion order is complex, 
            # but we can check the uppercase ones are before all lowercases
            # Just check the entry exists
            assert entry in CYRILLIC


# Tests for GERMAN constant

def test_german_contains_lowercase_ae():
    assert ('ä', 'ae') in GERMAN


def test_german_contains_uppercase_ae():
    assert ('Ä', 'Ae') in GERMAN


def test_german_contains_lowercase_oe():
    assert ('ö', 'oe') in GERMAN


def test_german_contains_uppercase_oe():
    assert ('Ö', 'Oe') in GERMAN


def test_german_contains_lowercase_ue():
    assert ('ü', 'ue') in GERMAN


def test_german_contains_uppercase_ue():
    assert ('Ü', 'Ue') in GERMAN


def test_german_length():
    # 3 lowercase + 3 uppercase = 6
    assert len(GERMAN) == 6


def test_german_no_duplicates():
    assert len(GERMAN) == len(set(GERMAN))


# Tests for GREEK constant

def test_greek_contains_lowercase_chi():
    assert ('χ', 'ch') in GREEK


def test_greek_contains_uppercase_chi():
    assert ('Χ', 'Ch') in GREEK


def test_greek_contains_uppercase_xi():
    assert ('Ξ', 'X') in GREEK


def test_greek_contains_uppercase_upsilon_hook():
    assert ('ϒ', 'Y') in GREEK


def test_greek_contains_lowercase_upsilon():
    assert ('υ', 'y') in GREEK


def test_greek_contains_lowercase_upsilon_tonos():
    assert ('ύ', 'y') in GREEK


def test_greek_contains_lowercase_upsilon_dialytika():
    assert ('ϋ', 'y') in GREEK


def test_greek_contains_lowercase_upsilon_dialytika_tonos():
    assert ('ΰ', 'y') in GREEK


def test_greek_no_duplicates():
    assert len(GREEK) == len(set(GREEK))


# Tests for PRE_TRANSLATIONS constant

def test_pre_translations_is_list():
    assert isinstance(PRE_TRANSLATIONS, list)


def test_pre_translations_contains_all_cyrillic():
    for entry in CYRILLIC:
        assert entry in PRE_TRANSLATIONS


def test_pre_translations_contains_all_german():
    for entry in GERMAN:
        assert entry in PRE_TRANSLATIONS


def test_pre_translations_contains_all_greek():
    for entry in GREEK:
        assert entry in PRE_TRANSLATIONS


def test_pre_translations_cyrillic_before_german():
    # CYRILLIC comes first in PRE_TRANSLATIONS = CYRILLIC + GERMAN + GREEK
    cyrillic_indices = [PRE_TRANSLATIONS.index(e) for e in CYRILLIC if e in PRE_TRANSLATIONS]
    german_indices = [PRE_TRANSLATIONS.index(e) for e in GERMAN if e in PRE_TRANSLATIONS]
    if cyrillic_indices and german_indices:
        assert max(cyrillic_indices) < min(german_indices)


def test_pre_translations_german_before_greek():
    # GERMAN comes before GREEK in PRE_TRANSLATIONS = CYRILLIC + GERMAN + GREEK
    german_indices = [PRE_TRANSLATIONS.index(e) for e in GERMAN if e in PRE_TRANSLATIONS]
    greek_indices = [PRE_TRANSLATIONS.index(e) for e in GREEK if e in PRE_TRANSLATIONS]
    if german_indices and greek_indices:
        assert max(german_indices) < min(greek_indices)


def test_pre_translations_length():
    expected_length = len(CYRILLIC) + len(GERMAN) + len(GREEK)
    assert len(PRE_TRANSLATIONS) == expected_length


def test_pre_translations_all_tuples():
    for entry in PRE_TRANSLATIONS:
        assert isinstance(entry, tuple)
        assert len(entry) == 2


def test_pre_translations_all_strings():
    for char, xlate in PRE_TRANSLATIONS:
        assert isinstance(char, str)
        assert isinstance(xlate, str)


def test_pre_translations_exact_value():
